insert into public.pos_products (company_id, name, category, product_type)
select '0e573ed8-ebe8-4e32-88aa-87100e838dab', s.name, s.category, s.product_type::public.pos_product_type
from seed s
on conflict (company_id, lower(name)) do update set
  category     = excluded.category,
  product_type = excluded.product_type,
  updated_at   = now();

-- --- variants ----------------------------------------------------------------

with seed (product_name, size, selling_price, target_margin_pct, sort_order) as (
  values
    ('Iced Latte', '12oz', 13000, 70, 0),
    ('Iced Latte', '16oz', 16000, 70, 1),
    ('Iced Latte', '22oz', 19000, 70, 2),
    ('Iced Americano', '16oz', 13000, 70, 3),
    ('Iced Americano', '22oz', 15500, 70, 4),
    ('Caramel Macchiato', '16oz', 18000, 70, 5),
    ('White Chocolate Mocha', '16oz', 18500, 70, 6),
    ('Matcha Latte', '16oz', 17500, 70, 7),
    ('Chocolate', '16oz', 16500, 70, 8),
    ('Strawberry Iced Tea', '16oz', 14000, 70, 9),
    ('Lychee Iced Tea', '16oz', 14000, 70, 10),
    ('Cheesecake Slice', 'Slice', 15000, 70, 11),
    ('Mango Float', 'Cup', 9500, 70, 12)
)
insert into public.pos_product_variants
  (company_id, product_id, size, selling_price, target_margin_pct, sort_order)
select '0e573ed8-ebe8-4e32-88aa-87100e838dab', p.id, s.size, s.selling_price, s.target_margin_pct, s.sort_order
from seed s
join public.pos_products p
  on p.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab' and lower(p.name) = lower(s.product_name)
on conflict (product_id, lower(size)) do update set
  selling_price     = excluded.selling_price,
  target_margin_pct = excluded.target_margin_pct,
  sort_order        = excluded.sort_order,
  updated_at        = now();

-- --- modifier groups and modifiers -------------------------------------------

with seed (product_name, name, min_select, max_select, sort_order) as (
  values
    ('Iced Latte', 'Add-ons', 0, 2, 0),
    ('Iced Americano', 'Add-ons', 0, 2, 1),
    ('Caramel Macchiato', 'Add-ons', 0, 2, 2),
    ('White Chocolate Mocha', 'Add-ons', 0, 2, 3)
),
resolved as (
  select
    (select p.id from public.pos_products p
      where p.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab' and lower(p.name) = lower(s.product_name)) as product_id,
    s.*
  from seed s
  where s.name is not null
)
insert into public.pos_modifier_groups
  (company_id, product_id, name, min_select, max_select, sort_order)
select '0e573ed8-ebe8-4e32-88aa-87100e838dab', r.product_id, r.name, r.min_select, r.max_select, r.sort_order
from resolved r
-- Identified by product plus name: several products each have an "Add-ons"
-- group, and they are not the same group.
where not exists (
  select 1 from public.pos_modifier_groups g
  where g.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab'
    and g.product_id is not distinct from r.product_id
    and lower(g.name) = lower(r.name)
);

with seed (product_name, group_name, name, price_delta, sort_order) as (
  values
    ('Iced Latte', 'Add-ons', 'Extra shot', 4000, 0),
    ('Iced Latte', 'Add-ons', 'Caramel drizzle', 2000, 1),
    ('Iced Americano', 'Add-ons', 'Extra shot', 4000, 2),
    ('Iced Americano', 'Add-ons', 'Caramel drizzle', 2000, 3),
    ('Caramel Macchiato', 'Add-ons', 'Extra shot', 4000, 4),
    ('Caramel Macchiato', 'Add-ons', 'Caramel drizzle', 2000, 5),
    ('White Chocolate Mocha', 'Add-ons', 'Extra shot', 4000, 6),
    ('White Chocolate Mocha', 'Add-ons', 'Caramel drizzle', 2000, 7)
),
resolved as (
  select g.id as group_id, s.name, s.price_delta, s.sort_order
  from seed s
  join public.pos_modifier_groups g
    on g.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab'
   and lower(g.name) = lower(s.group_name)
   and g.product_id is not distinct from
       (select p.id from public.pos_products p
         where p.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab' and lower(p.name) = lower(s.product_name))
  where s.name is not null
)
insert into public.pos_modifiers (company_id, group_id, name, price_delta, sort_order)
select '0e573ed8-ebe8-4e32-88aa-87100e838dab', r.group_id, r.name, r.price_delta, r.sort_order
from resolved r
where not exists (
  select 1 from public.pos_modifiers m
  where m.group_id = r.group_id and lower(m.name) = lower(r.name)
);

