insert into public.pos_recipe_lines (company_id, owner_id, owner_type, item_id, qty)
select '0e573ed8-ebe8-4e32-88aa-87100e838dab', owner.id, 'prep', ing.id, s.qty
from seed s
join public.pos_items owner
  on owner.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab' and lower(owner.name) = lower(s.owner_name)
join public.pos_items ing
  on ing.company_id = '0e573ed8-ebe8-4e32-88aa-87100e838dab' and lower(ing.name) = lower(s.item_name)
on conflict (owner_id, item_id) do update set qty = excluded.qty, updated_at = now();

